mapper.select:
SELECT age_group AS ageGroup, NVL(SUM(archive_count), 0) AS archiveCount, NVL(SUM(outpatient_count), 0) AS outpatientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_AGE a LEFT JOIN TR_DEPT_DICT d ON a.dept_code = d.dept_code WHERE a.stat_date BETWEEN #{startDate} AND #{endDate}
AND a.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY a.age_group, a.patient_type ORDER BY TO_NUMBER(REGEXP_SUBSTR(a.age_group, '[0-9]+')) ASC

SELECT insurance_name AS insuranceName, NVL(SUM(patient_count), 0) AS patientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_INSUR i LEFT JOIN TR_DEPT_DICT d ON i.dept_code = d.dept_code WHERE i.stat_date BETWEEN #{startDate} AND #{endDate}
AND i.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY i.insurance_name, i.patient_type ORDER BY patientCount DESC

SELECT identity_name AS identityName, NVL(SUM(patient_count), 0) AS patientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_IDTY t LEFT JOIN TR_DEPT_DICT d ON t.dept_code = d.dept_code WHERE t.stat_date BETWEEN #{startDate} AND #{endDate}
AND t.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY t.identity_name, t.patient_type, t.dept_code, d.dept_name ORDER BY patientCount DESC

SELECT source_name AS sourceName, NVL(SUM(patient_count), 0) AS patientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_REG r LEFT JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate}
AND r.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY r.source_name, r.patient_type ORDER BY patientCount DESC

SELECT source_name AS sourceName, NVL(SUM(patient_count), 0) AS patientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_ARC a LEFT JOIN TR_DEPT_DICT d ON a.dept_code = d.dept_code WHERE a.stat_date BETWEEN #{startDate} AND #{endDate}
AND a.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY a.source_name, a.patient_type ORDER BY patientCount DESC
